(async()=>{const items=await fetch('programme.json').then(r=>r.json());const rows=(a,start)=>'<ol class="order">'+a.map(([n,d],i)=>`<li><span class="num">${String(start+i).padStart(2,'0')}</span><div><b>${n}</b>${d?`<small>${d}</small>`:''}</div></li>`).join('')+'</ol>';const pages=[['Welcome',`<div class="cover"><img class="logo" src="../assets/mzys-logo.jpg" alt="MZYS logo"><p class="label">2026 YOUTH WEEK · GRAND FINALE</p><h2>Sunday<br>Thanksgiving Service</h2><p class="theme">UNSHAKABLE FOUNDATION</p><p>1 Corinthians 3:11</p><p>Sunday 15 November 2026<br><b>8:00 a.m.</b></p><p class="note">The Eternal Sacred Order of the Cherubim and Seraphim<br>National Headquarters Annex Cathedral, Abuja</p><p class="note">31 Oyo Street, Area 2, Garki Section 1, Abuja</p></div>`],['Our foundation',`<p class="label">THE THEME</p><h2>Unshakable Foundation</h2><p class="verse">“For other foundation can no man lay than that is laid, which is Jesus Christ.”</p><p>1 Corinthians 3:11 · King James Version</p><p>We gather with grateful hearts to celebrate God’s faithfulness and the sure foundation we have in Jesus Christ.</p>`],['Worship & readings',`<p class="label">ORDER OF SERVICE · PART ONE</p><h2>Enter with thanksgiving</h2>${rows(items.slice(0,9),1)}`],['Prayer & thanksgiving',`<p class="label">ORDER OF SERVICE · PART TWO</p><h2>Give thanks with joy</h2>${rows(items.slice(9),10)}`],['Hymn guide',`<p class="label">SING WITH US</p><h2>Hymns for the service</h2><div class="hymns">${[['18','Processional'],['257','Opening'],['359','First Lesson song'],['197','Sermon song'],['355','Alms collection'],['437','Collection / closing']].map(([n,t])=>`<div><strong>${n}</strong><span>${t}</span></div>`).join('')}</div><p class="note">Please follow these numbers in your church hymnbook. Hymn lyrics and the First and Second Lesson passages are not included in this edition.</p>`],['Go in thanksgiving',`<p class="label">ROOTED IN CHRIST · RISING IN PURPOSE</p><h2>Carry the thanksgiving with you.</h2><p class="blessing">May our gratitude become a life of faith, service and love, firmly built on Christ.</p><p>Thank you for celebrating the 2026 Youth Week with us.</p><p><a class="theme" href="../#maker">Put yourself in the picture →</a></p><p class="note">Add your photo to the official Youth Week flyer and share the joy with our church family.</p><p class="note">2026 MZYS Youth Week Committee</p>`]];const page=document.querySelector('#page'),contents=document.querySelector('#contents');page.innerHTML=pages.map(([name,body],i)=>`<section id="section-${i}" class="programme-section">${body}</section>`).join('');pages.forEach(([name],i)=>{const a=document.createElement('a');a.href=`#section-${i}`;a.textContent=name;contents.append(a)});const status=document.querySelector('#status');let registration;if('serviceWorker'in navigator){registration=navigator.serviceWorker.register('sw.js');registration.catch(()=>status.textContent='Offline saving is unavailable. You can still download the print programme.')}document.querySelector('#save').onclick=async()=>{try{if(!registration)throw Error();await registration;await navigator.serviceWorker.ready;const cache=await caches.open('mzys-sunday-v2');await cache.addAll(['./','index.html','book.css','book.js','programme.json','../assets/mzys-logo.jpg','../favicon.ico','Sunday_Thanksgiving_Programme.pdf']);status.textContent='Saved for offline use on this device. Reopen this same link after disconnecting.';document.querySelector('#save').textContent='Saved ✓'}catch{status.textContent='Could not save offline. Please check your connection and try again, or download the print programme.'}}})().catch(()=>document.querySelector('#status').textContent='Unable to load the programme. Please reconnect and refresh.');
